        in = new BufferedInputStream(System.in, 1024 * 10);
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out, "ASCII"), 1024 * 10));
        solve(args);
        writer.flush();
    }

    private static void solve(String[] args) throws IOException {
        int n = next();
        int k = next();

        int[] l = new int[k];
        int[] r = new int[k];
        for (int i = 0; i < k; i++) {
            l[i] = next();
            r[i] = next();
        }

        @SuppressWarnings("unchecked")
        List<Interval>[] dp = new List[2 * k + 1];
        for (int i = 0; i < dp.length; i++) {
            dp[i] = new ArrayList<>();
        }
        dp[0].add(new Interval(0, 0));

        int prev = 0;
        for (int i = 0; i < k; i++) {
            @SuppressWarnings("unchecked")
            List<Interval>[] next = new List[dp.length];
            for (int ii = 0; ii < dp.length; ii++) {
                next[ii] = new ArrayList<>();
            }

            int delta = l[i] - prev;
            for (int index = 0; index < dp.length; index++) {
                if (index % 2 == 0) {
                    List<Interval> t = dp[index];
                    for (Interval interval : t) {
                        interval.l += delta;
                        interval.r += delta;
                    }
                }
            }
            delta = r[i] - l[i];
            for (int ii = 0; ii < dp.length; ii++) {
                if (ii % 2 == 0) {
                    for (Interval interval : dp[ii]) {
                        next[ii].add(new Interval(interval.l + delta, interval.r + delta));
                        next[ii + 1].add(new Interval(interval.l, interval.r + delta));
                        next[ii + 2].add(new Interval(interval.l, interval.r + delta));
                    }
                } else {
                    for (Interval interval : dp[ii]) {
                        next[ii].add(new Interval(interval.l, interval.r));
                        next[ii + 1].add(new Interval(interval.l, interval.r + delta));
                        next[ii + 2].add(new Interval(interval.l, interval.r + delta));
                    }
                }
            }

            prev = r[i];
            for (int index = 0; index < dp.length; index++) {
                dp[index].clear();

                Interval pr = null;
                List<Interval> sorted = new ArrayList<>(next[index]);
                sorted.sort((a, b) -> Integer.compare(a.l, b.l));
                for (Interval interval : sorted) {
                    if (interval.l > n)
                        break;
                    if (pr != null && pr.r >= interval.l) {
                        pr.r = Math.max(pr.r, interval.r);
                    } else {
                        if (pr != null && !find(dp, pr, index))
                            dp[index].add(pr);
                        pr = interval;
                    }
                }
                if (pr != null && !find(dp, pr, index))
                    dp[index].add(pr);
            }
        }

        {
            int delta = 2 * n - prev;
            for (int index = 0; index < dp.length; index++) {
                if (index % 2 == 0) {
                    List<Interval> t = dp[index];
                    for (Interval interval : t) {
                        interval.l += delta;
                        interval.r += delta;
                    }
                }
            }
        }

        for (int i = 0; i < dp.length; i++) {
            for (Interval interval : dp[i]) {
                if (interval.l <= n && interval.r >= n) {
                    writer.println("Full");
                    writer.println(i);
                    return;
                }
            }
        }

        writer.println("Hungry");
    }

    private static boolean find(List<Interval>[] dp, Interval value, int index) {
        for (int i = index - 2; i >= 0; i--) {
            int ind = Collections.binarySearch(dp[i], value, (a, b) -> Integer.compare(a.l, b.l));
            if (ind < 0) {
                ind = (~ind) - 1;
                if (ind > 0 && dp[i].get(ind).r >= value.r) {
                    return true;
                }
            } else {
                if (dp[i].get(ind).r >= value.r)
                    return true;
            }
        }

        return false;
    }

    private static int next() throws IOException {
        int c;
        int res = 0;
        do {
            c = in.read();
            if (c == -1)
                return res;
        } while (c < '0' || c > '9');
        res = c - '0';
        while (true) {
            c = in.read();
            if (c < '0' || c > '9')
                return res;
            res *= 10;
            res += c - '0';
        }
    }

    private static class Interval {
        int l, r;

        Interval(int l, int r) {
            this.l = l;
            this.r = r;
        }
    }
}
